#!/usr/bin/env node
'use strict';
/**
 * The model travels inside the `.drawio` — and comes back whole?
 *
 * #2 proved by READING THE CODE that an `<object>` attribute survives the
 * round-trip, and listed as uncertainty 7(a) precisely what it couldn't test:
 *
 *   > "I didn't open a file generated by the real app, nor did I do a real
 *   >  write round-trip. The two claims that would most deserve that test:
 *   >  (a) literal preservation of a multi-line YAML after editing and saving."
 *
 * The headless binary (#9/#10) closes that uncertainty: `drawio -x -f xml`
 * makes the app decode and RE-SERIALIZE the file through its own codec. If
 * the embedded model survives that, the `.drawio` is its own persistence
 * format and there's no second file to fall out of sync with.
 *
 *   node tools/check-roundtrip.cjs [drawio-binary]
 */

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const { binary } = require(path.join(__dirname, '..', 'tools', 'drawio.cjs'));
const DRAWIO = binary(process.argv[2]);
const TMP = process.env.TMPDIR || '/tmp';

const UNESC = { '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&apos;': "'" };
function unescape(s) {
  return s.replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&(amp|lt|gt|quot|#39|apos);/g, m => UNESC[m]);
}

/** Extracts the model embedded in the `<object>`'s `panlabsModelo` attribute. */
function extract(xml) {
  const m = /panlabsModelo="([^"]*)"/.exec(xml);
  if (!m) return null;
  return JSON.parse(unescape(m[1]));
}

const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);

let failures = 0;
const files = fs.readdirSync(path.join(ROOT, 'output')).filter(f => f.endsWith('.drawio'));
if (!files.length) { console.log('  (no .drawio in output/ — run the engine first)'); process.exit(1); }

const hasApp = fs.existsSync(DRAWIO);
if (!hasApp) console.log(`  draw.io headless missing at ${DRAWIO} — static layer only.\n`);

for (const file of files) {
  const filePath = path.join(ROOT, 'output', file);
  const xml = fs.readFileSync(filePath, 'utf8');
  const name = file.replace(/\.drawio$/, '');
  // style variants (dashed/animated flow) come out of the same model under a
  // different file name; with no matching model there's nothing to compare
  const modelPath = path.join(ROOT, 'models', name + '.json');
  if (!fs.existsSync(modelPath)) { console.log(`  ${file}\n    (variant with no model of its own — skipped)`); continue; }
  const source = JSON.parse(fs.readFileSync(modelPath, 'utf8'));

  // 1. static: what was written to the file is the source model
  const readBack = extract(xml);
  const ok1 = readBack && equal(readBack, source);
  console.log(`  ${file}`);
  console.log(`    extracted from the file          ${ok1 ? '✓' : '✗'}`);
  if (!ok1) { failures++; if (readBack) console.log(`        differs from the source model`); else console.log('        panlabsModelo attribute missing'); }

  // 2. the app decodes and re-serializes through its own codec
  if (!hasApp) continue;
  const output = path.join(TMP, `rt-${name}.drawio`);
  try {
    execFileSync('xvfb-run', ['-a', DRAWIO, '-x', '-f', 'xml', '--no-sandbox', '--disable-gpu', '-o', output, filePath],
      { stdio: ['ignore', 'ignore', 'ignore'] });
  } catch (e) { console.log(`    round-trip through the app          ✗ (failed to export)`); failures++; continue; }

  const after = fs.readFileSync(output, 'utf8');
  const readBack2 = extract(after);
  const ok2 = readBack2 && equal(readBack2, source);
  console.log(`    round-trip through the app          ${ok2 ? '✓' : '✗'}  (${after.length} bytes, host=${/host="([^"]*)"/.exec(after)?.[1]})`);
  if (!ok2) { failures++; console.log(readBack2 ? '        the app altered the embedded model' : '        the app ate the attribute'); }

  // 3. does the dossier — which the engine never reads — also come back whole?
  if (source.dossier) {
    const ok3 = readBack2 && equal(readBack2.dossier, source.dossier);
    console.log(`    opaque dossier intact         ${ok3 ? '✓' : '✗'}`);
    if (!ok3) failures++;
  }
  fs.unlinkSync(output);
}

console.log(failures ? `\n  ✗ ${failures} round-trip failure(s)` : "\n  ✓ the model survives draw.io's own codec.");
process.exit(failures ? 1 : 0);
